function fileMenu(){menu([{icon:'check',label:'Select all',run:()=>{activePane().selected=new Set(activePane().items.map(fileKey));renderFiles();}},{icon:'copy',label:'Bookmarks',run:bookmarks},{icon:'refresh',label:'Refresh',run:refresh},{icon:'search',label:'Filter current folder',run:async()=>{const q=await ask('Find file','','Filename contains');if(q===null)return;await loadPane(state.active);activePane().items=activePane().items.filter(f=>f.name.toLowerCase().includes(q.toLowerCase()));renderFiles();}},{icon:'compass',label:'Go to path',run:async()=>{const p=await ask('Go to path',activePane().path);if(p)await navigate(state.active,{path:p,archive:'',entry:''});}},{icon:'check',label:'Show hidden files',end:pref.hidden?'✓':'',run:async()=>{pref.hidden=!pref.hidden;savePref();await refresh();}},{icon:'settings',label:'Preferences',run:preferences},{icon:'info',label:'About',run:about}]);}
function createMenu(){const rows=[];if(!activePane().archive){rows.push({label:'New folder',icon:'folder',run:()=>createFile(true)},{label:'New text file',icon:'text',run:()=>createFile(false)});if(state.clipboard)rows.push({label:`Paste ${state.clipboard.name}`,icon:'copy',run:paste});}if(!rows.length)return toast('Extract the archive to create files inside a folder.');options('Create / Paste',rows);}
async function createFile(folder){const name=await ask(folder?'New folder':'New file',folder?'New folder':'Untitled.txt');if(!name)return;const path=await rpc('create',{path:activePane().path,name,folder});await refresh();if(!folder)await openText({path});}
