function fileKey(f){return f.archive?f.archive+'!/'+f.entry:f.path;}
function selectedFiles(){const p=activePane();if(!p.selected)p.selected=new Set();return p.items.filter(f=>p.selected.has(fileKey(f)));}
function toggleFile(f,index){state.active=index;const p=activePane();if(!p.selected)p.selected=new Set();const key=fileKey(f);p.selected.has(key)?p.selected.delete(key):p.selected.add(key);renderFiles();}
function clearSelection(){activePane().selected=new Set();renderFiles();}
function selectionBar(){const bottom=$('#bottom');bottom.replaceChildren(iconButton('check','Select all',()=>{activePane().selected=new Set(activePane().items.map(fileKey));renderFiles();}),iconButton('switch','Invert file selection',()=>{const p=activePane();p.selected=new Set(p.items.filter(f=>!p.selected.has(fileKey(f))).map(fileKey));renderFiles();}),iconButton('close','Clear selection',clearSelection),iconButton('more','Selected file actions',()=>fileActions(selectedFiles()[0])),iconButton('info','Selection properties',()=>fileProperties(selectedFiles())));}
