 if(state.dex.tab==='explorer'){tree.setAttribute('role','tree');tree.setAttribute('aria-label','DEX packages and classes');await dexBranch(tree,'');tree.scrollTop=state.dex.scroll||0;tree.onscroll=()=>state.dex.scroll=tree.scrollTop;return;}
