 const draw=q=>{const list=d.querySelector('.navRows');list.replaceChildren();const filtered=rows.filter(r=>(r.name+' '+r.detail).toLowerCase().includes(q.toLowerCase()));for(const r of filtered){const b=document.createElement('button');b.className='navRow';b.innerHTML='<span class="memberIcon '+r.kind+'">'+({class:'C',field:'F',method:'M',string:'S'})[r.kind]+'</span><span class="navText">'+esc(r.name)+(r.kind==='string'?'':'<small>'+esc(r.detail)+'</small>')+'</span>';b.title=r.signature;hold(b,()=>memberActions(r),()=>jumpMember(r));list.append(b);}if(!filtered.length)list.innerHTML='<p class="muted">No '+(navigationStrings?'string occurrences':'members')+' found.</p>';};
