function hold(button,longPress,click){let timer,held=false,x=0,y=0;button.onpointerdown=e=>{held=false;x=e.clientX;y=e.clientY;timer=setTimeout(()=>{held=true;act(longPress);},500);};button.onpointerup=button.onpointercancel=()=>clearTimeout(timer);button.onpointermove=e=>{if(Math.abs(e.clientX-x)>8||Math.abs(e.clientY-y)>8)clearTimeout(timer);};button.oncontextmenu=e=>{e.preventDefault();held=true;act(longPress);};button.onclick=()=>{if(held){held=false;return;}act(click);};}
const navigationOptions={class:[['usages','Find usages'],['subclasses','Find subclasses'],['signature','Copy class signature'],['frida','Copy as frida snippet'],['xposed','Copy as xposed snippet']],field:[['usages','Find usages'],['signature','Copy field signature'],['get','Copy field get code'],['put','Copy field put code'],['frida','Copy as frida snippet'],['xposed','Copy as xposed snippet']],method:[['usages','Find usages'],['overrides','Find overriding methods'],['signature','Copy method signature'],['code','Copy method code'],['frida','Copy as frida snippet'],['xposed','Copy as xposed snippet']]};
