async function exportText(text,name){const dir=await ask('Export to folder',state.info.permission?state.info.home+'/Download':state.info.workspace);if(!dir)return;const filename=await ask('Filename',name);if(filename){const path=await rpc('exportText',{path:dir,name:filename,text});alertBox('Exported',path);}}
function preferences(){const currentFont=state.screen==='editor'?editorFont():pref.font;const d=dialog('Preferences',`<label>Editor font size: <span id="fontSizeLabel">${currentFont}</span> px</label><input id="fontSize" type="range" min="4" max="32" step="0.5" value="${currentFont}"><label class="checkrow" style="font-size:16px!important"><input id="prefWrap" type="checkbox" ${pref.wrap?'checked':''}>Soft wrap</label><label class="checkrow" style="font-size:16px!important"><input id="prefLines" type="checkbox" ${pref.lines?'checked':''}>Line numbers</label><label class="checkrow" style="font-size:16px!important"><input id="prefHidden" type="checkbox" ${pref.hidden?'checked':''}>Show hidden files</label><label class="toggleRow"><span>Animations</span><input id="prefMotion" type="checkbox" ${pref.motion!==false?'checked':''}></label><label class="toggleRow"><span>Pinch to zoom in editors</span><input id="prefPinch" type="checkbox" ${pref.pinchZoom!==false?'checked':''}></label>`,[['Cancel',closeModal],['Apply',async()=>{pref.font=Number($('#fontSize').value);if(state.screen==='editor'){if(!pref.fonts)pref.fonts={};pref.fonts[fontKey()]=pref.font;}pref.wrap=$('#prefWrap').checked;pref.lines=$('#prefLines').checked;pref.hidden=$('#prefHidden').checked;pref.motion=$('#prefMotion').checked;pref.pinchZoom=$('#prefPinch').checked;savePref();closeModal();if(state.screen==='editor'){state.cm.setOption('lineWrapping',pref.wrap);state.cm.setOption('lineNumbers',pref.lines);state.cm.getWrapperElement().style.fontSize=editorFont()+'px';state.cm.refresh();}else if(state.screen==='files')await refresh();}]]);d.querySelector('#fontSize').oninput=e=>$('#fontSizeLabel').textContent=e.target.value;}
async function openDrawer(drag=false){closeMenu();const layer=$('#drawerLayer');if(layer.children.length){if(!drag)closeDrawer();return;}clearLayer(layer,false);layer.innerHTML=`<div class="drawerShade"></div><aside class="drawer" aria-label="Navigation" role="navigation"><div class="drawerHead"><div class="drawerTop"><div class="brandMark">DB</div><div class="titleblock"><div class="title">DB Manager</div><div class="subtitle">${esc(storage.get('cyber-name')||'LOCAL WORKSPACE')}</div></div><button class="iconbtn" id="themeToggle" aria-label="Toggle theme">${icon('sun')}</button><button class="iconbtn" id="drawerMore" aria-label="Navigation menu">${icon('more')}</button></div></div><div id="drawerDocument"></div><button class="sectionLabel" aria-expanded="true" data-group="storageRows">Local ${icon('up')}</button><div class="drawerGroup" id="storageRows"></div><button class="sectionLabel" aria-expanded="true" data-group="networkRows">Network ${icon('up')}</button><div class="drawerGroup" id="networkRows"></div><button class="sectionLabel" aria-expanded="true" data-group="backgroundRows">Background ${icon('up')}</button><div class="drawerGroup" id="backgroundRows"></div><button class="sectionLabel" aria-expanded="true" data-group="toolRows">Tools ${icon('up')}</button><div class="drawerGroup" id="toolRows"></div></aside>`;if(drag)layer.querySelector('.drawer').classList.add('dragging');else{const surface=layer.querySelector('.drawer');surface.classList.add('entering');setTimeout(()=>surface.classList.remove('entering'),240);}layer.querySelector('.drawerShade').onclick=closeDrawer;$('#drawerMore').onclick=()=>state.screen==='editor'?editorMenu():drawerMenu();$('#themeToggle').onclick=()=>{pref.light=!pref.light;savePref();};layer.querySelector('.brandMark').onclick=about;layer.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{const open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));expandGroup($('#'+b.dataset.group),open);});
 function row(parent,ic,label,fn,detail=''){const b=document.createElement('button');b.className='drawerRow';b.innerHTML=`<span class="circleicon">${icon(ic)}</span><span class="storage">${esc(label)}${detail}</span>`;b.onclick=()=>act(async()=>{closeDrawer();if(state.screen==='editor'&&!await canLeave())return;if(state.screen==='editor'&&state.disposeEditor)state.disposeEditor();await fn();});layer.querySelector(parent).append(b);return b;}
 const drawer=layer.querySelector('.drawer');
 if(state.screen==='editor'){
  const doc=document.createElement('button');doc.className='drawerRow currentDocument';doc.innerHTML=icon('edit')+'<span class="storage">'+esc((state.editor.dirty?'*':'')+state.editor.name)+'<small>'+esc(state.editor.mode==='java'?'Java · Editable':state.editor.kind==='dex'?'Smali · Editable':'Text editor')+'</small></span>';
  doc.onclick=closeDrawer;layer.querySelector('#drawerDocument').append(doc);
 }
 row('#storageRows','phone','Root Directory',()=>navigate(state.active,{path:'/',archive:'',entry:''}));
 const storageRow=row('#storageRows','sd','Storage Directory',()=>navigate(state.active,{path:state.info.home,archive:'',entry:''}),'<div class="small">Reading storage…</div>');
 row('#storageRows','folder','App Workspace',()=>navigate(state.active,{path:state.info.workspace,archive:'',entry:''}));row('#networkRows','network','FTP / FTPS connection',ftpPage);row('#backgroundRows','history',`${pending.size} current operations`,backgroundPage);
 for(const [ic,label,fn]of [['trash','Recycle Bin',recyclePage],['plugin','Plugin Manager',pluginPage],['remote','Remote Manager',()=>servicePage('remote')],['layers','Installed Apps',appsPage],['text','Text Editor',newText],['terminal','Terminal Simulator',terminalPage],['network','MCP Service',()=>servicePage('mcp')],['history','Activity Record',logPage],['more','More Tools',moreTools]])row('#toolRows',ic,label,fn);
 try{const disk=await rpc('disk',{path:state.info.home});if(!drawer.isConnected)return;storageRow.querySelector('.storage').innerHTML='Storage Directory<div class="meter"><span style="width:'+ (disk.total?(1-disk.free/disk.total)*100:0)+'%"></span></div><div class="small">'+size(disk.total-disk.free)+' used, '+size(disk.free)+' available</div>';}catch(error){if(drawer.isConnected)storageRow.querySelector('.small').textContent='Storage information unavailable';}
}
function drawerMenu(){menu([{icon:'copy',label:'Bookmarks',run:()=>{closeDrawer();bookmarks();}},{icon:'refresh',label:'Refresh',run:async()=>{closeDrawer();if(state.screen==='files')await refresh();}},{icon:'settings',label:'Preferences',run:()=>{closeDrawer();preferences();}},{icon:'info',label:'About',run:()=>{closeDrawer();about();}}]);}

function toolPage(title,subtitle=''){state.previous=state.screen==='dex'?'dex':'files';state.screen='tool';header(title,subtitle,[{icon:'close',label:'Close tool',run:window.goBack}]);$('#subbar').innerHTML='';$('#bottom').innerHTML='';$('#content').classList.remove('javaEditor');$('#content').innerHTML='<div class="toolpage" id="toolbody"></div>';return $('#toolbody');}
async function appsPage(){const body=toolPage('Installed Apps','Tap an app to inspect its APK');body.innerHTML='<div class="searchline"><input placeholder="Search installed apps" aria-label="Search installed apps"></div><div id="appsRows"></div>';const apps=await rpc('apps');function render(q){$('#appsRows').innerHTML=apps.filter(x=>(x.name+' '+x.package).toLowerCase().includes(q.toLowerCase())).map((x)=>`<button class="listrow" data-app-path="${esc(x.path)}">${icon('apk')}<span class="main">${esc(x.name)}<small>${esc(x.package)}</small></span></button>`).join('');document.querySelectorAll('[data-app-path]').forEach(b=>b.onclick=()=>act(()=>showApk({path:b.dataset.appPath})));}body.querySelector('input').oninput=e=>render(e.target.value);render('');}
async function recyclePage(){const body=toolPage('Recycle Bin','Restore files to their original location');const rows=await rpc('recycleList');if(!rows.length){body.innerHTML='<div class="empty">Recycle Bin is empty.</div>';return;}for(const r of rows){const b=document.createElement('button');b.className='listrow';b.innerHTML=icon('trash')+`<span class="main">${esc(r.name)}<small>${esc(r.path)}</small><small>${date(r.time)}</small></span>`;b.onclick=()=>options(r.name,[{icon:'undo',label:'Restore',run:async()=>{await rpc('restore',{id:r.id});await recyclePage();}},{icon:'trash',label:'Delete permanently',run:async()=>{if(await confirmBox('Delete permanently?',r.name+' cannot be restored after this.','Delete')){await rpc('purge',{id:r.id});await recyclePage();}}}]);body.append(b);}}
async function logPage(){const body=toolPage('Activity Record');const rows=await rpc('log');body.innerHTML=rows.length?rows.map(x=>`<div class="listrow">${icon('history')}<div class="main">${esc(x.text)}<small>${date(x.time)}</small></div></div>`).join(''):'<div class="empty">File changes and completed tasks appear here.</div>';}
async function newText(){const path=await ask('Folder',state.info.workspace);if(!path)return;const name=await ask('New text file','Untitled.txt');if(!name)return;const file=await rpc('create',{path,name,folder:false});await openText({path:file});}
function terminalPage(){const body=toolPage('Terminal Simulator','Commands run with this app’s permissions');body.innerHTML=`<p>Working directory</p><input class="toolinput" id="terminalPath" value="${esc(activePane().archive?state.info.workspace:activePane().path)}"><pre class="terminal" id="terminalOutput">DB Manager shell\n</pre><div class="searchline"><input id="command" placeholder="Enter shell command" spellcheck="false" aria-label="Shell command"><button id="runCommand">RUN</button></div>`;const run=()=>act(async()=>{const command=$('#command').value;if(!command.trim())return;$('#command').value='';$('#terminalOutput').textContent+='\n$ '+command+'\n';const text=await rpc('terminal',{command,path:$('#terminalPath').value});$('#terminalOutput').textContent+=text+'\n';$('#terminalOutput').scrollIntoView({block:'end'});});$('#runCommand').onclick=run;$('#command').onkeydown=e=>{if(e.key==='Enter')run();};}
async function pluginPage(){const body=toolPage('Plugin Manager','Local shell-script plugins');body.innerHTML='<p>Import a .sh script. It runs only when you choose Run, with this app’s permissions.</p><button class="primary" id="importPlugin">IMPORT SCRIPT</button><div id="pluginRows"></div>';$('#importPlugin').onclick=()=>act(async()=>{const path=await ask('Script path',state.info.home+'/Download/plugin.sh');if(path){await rpc('plugins',{op:'import',path});await pluginPage();}});const rows=await rpc('plugins');for(const name of rows){const b=document.createElement('button');b.className='listrow';b.innerHTML=icon('plugin')+`<span class="main">${esc(name)}</span>`;b.onclick=()=>options(name,[{icon:'play',label:'Run',run:async()=>{if(await confirmBox('Run script?',name,'Run')){const text=await rpc('plugins',{op:'run',name});alertBox('Script output',text);}}},{icon:'trash',label:'Remove',run:async()=>{if(await confirmBox('Remove plugin?',name,'Remove')){await rpc('plugins',{op:'remove',name});await pluginPage();}}}]);$('#pluginRows').append(b);}if(!rows.length)$('#pluginRows').innerHTML='<div class="empty">No scripts imported.</div>';}
async function servicePage(kind){const body=toolPage(kind==='mcp'?'MCP Service':'Remote Manager',kind==='mcp'?'Local HTTP · Read-only tools':'Share a folder on your local network');const status=await rpc('service',{kind});const current=status.servers.find(x=>x.kind===kind);body.innerHTML=`<div class="banner">${kind==='mcp'?'Provides list_files and read_text at localhost:8766/mcp. Connect using the displayed Bearer token.':'Open the displayed URL from another device on the same network to browse and download files.'} The service stops when the app process closes.</div><p>Shared folder</p><input class="toolinput" id="sharePath" value="${esc(current?current.root:activePane().archive?state.info.workspace:activePane().path)}" ${current?'disabled':''}>${current?`<p><span class="pill">RUNNING</span></p><p class="break">${current.urls.map(esc).join('<br>')||'No network address available'}</p><p class="break">Bearer token: ${esc(current.token)}</p><button class="primary" id="copyService">COPY CONNECTION</button>`:''}<button class="primary" id="toggleService">${current?'STOP':'START'}</button>`;$('#toggleService').onclick=()=>act(async()=>{await rpc('service',{kind,op:current?'stop':'start',path:$('#sharePath').value});await servicePage(kind);});if($('#copyService'))$('#copyService').onclick=()=>act(async()=>{await rpc('clipboard',{text:current.urls.join('\n')+(kind==='mcp'?'\nAuthorization: Bearer '+current.token:'')});toast('Connection copied');});}
function backgroundPage(){const body=toolPage('Background');body.innerHTML=`<p>${pending.size} current native operations.</p><p>File and decompilation tasks run off the UI thread. Remote/MCP services require the app process to stay alive.</p><button class="primary" id="services">VIEW SERVICES</button>`;$('#services').onclick=()=>options('Services',[{label:'Remote Manager',icon:'remote',run:()=>servicePage('remote')},{label:'MCP Service',icon:'network',run:()=>servicePage('mcp')}]);}
let ftpConfig=null,ftpPath='/';function ftpPage(){const body=toolPage('Network connection','FTP / explicit FTPS');body.innerHTML=`<p>Server</p><input class="toolinput" id="ftpHost" placeholder="ftp.example.com" value="${esc((ftpConfig && ftpConfig.host)||'')}"><p>Port</p><input class="toolinput" id="ftpPort" type="number" value="${(ftpConfig && ftpConfig.port)||21}"><p>Username</p><input class="toolinput" id="ftpUser" autocomplete="off" value="${esc((ftpConfig && ftpConfig.user)||'')}"><p>Password</p><input class="toolinput" id="ftpPass" type="password" autocomplete="off"><label><input type="checkbox" id="ftpTls" checked> Use TLS (FTPS)</label><br><button class="primary" id="connectFtp">CONNECT</button>`;$('#connectFtp').onclick=()=>act(async()=>{const host=$('#ftpHost').value.trim();if(!host)return toast('Enter a server address');ftpConfig={host,port:Number($('#ftpPort').value)||21,user:$('#ftpUser').value,password:$('#ftpPass').value,tls:$('#ftpTls').checked};ftpPath='/';await ftpBrowse();});}
async function ftpBrowse(){const rows=await rpc('ftp',{...ftpConfig,remote:ftpPath});const body=toolPage('FTP: '+ftpConfig.host,ftpPath);body.innerHTML='<button class="primary" id="ftpUp">PARENT</button><button class="primary" id="ftpUpload">UPLOAD FILE</button><div id="ftpRows"></div>';$('#ftpUp').onclick=()=>act(async()=>{const p=ftpPath.replace(/\/$/,'').split('/');p.pop();ftpPath=p.join('/')||'/';await ftpBrowse();});$('#ftpUpload').onclick=()=>act(async()=>{const local=await ask('Local file path',state.info.home+'/Download/');if(!local)return;const name=local.split('/').pop();if(await confirmBox('Upload file?',name+' to '+ftpPath+'. An existing server file with this name will be replaced.','Upload')){await rpc('ftp',{...ftpConfig,op:'upload',local,remote:ftpPath.replace(/\/$/,'')+'/'+name});await ftpBrowse();}});for(const f of rows){const b=document.createElement('button');b.className='listrow';b.innerHTML=icon(f.dir?'folder':'file')+`<span class="main">${esc(f.name)}<small>${f.dir?'Folder':size(f.size)}</small></span>`;b.onclick=()=>act(async()=>{const remote=ftpPath.replace(/\/$/,'')+'/'+f.name;if(f.dir){ftpPath=remote;await ftpBrowse();}else{const local=await ask('Download to',state.info.workspace+'/'+f.name);if(local){await rpc('ftp',{...ftpConfig,op:'download',remote,local});toast('Downloaded '+local);}}});$('#ftpRows').append(b);}}
function moreTools(){options('More Tools',[{icon:'apk',label:'Inspect this app’s APK',run:()=>showApk({path:state.info.ownApk})},{icon:'settings',label:'Preferences',run:preferences},{icon:'phone',label:'Storage permission',run:()=>rpc('permission')},{icon:'info',label:'User guide',run:guide},{icon:'info',label:'About DB Manager',run:about}]);}
function guide(){alertBox('User guide','Files: tap to open; long press for file operations. Use + to create or paste.\n\nAPK → View → classes.dex. Open a class; edit Smali or use View Java. Java is editable. Save compiles into the temporary DEX project. Back also compiles unsaved code; errors keep the editor open.\n\nEditor/DEX menu → Save and sign APK saves to the source, keeps a backup, and verifies V1/V2/V3 before offering Install. Save project writes unsigned changes. Export creates a separate copy.\n\nNot every decompiled Java file is valid source. Correct compiler errors or edit Smali. Keep package/class names unchanged.\n\nPinch resizes code. Text size / Zoom has buttons, slider and Reset. Find and replace edits the live buffer and supports Undo.\n\nSigning uses a public development certificate. Android permissions and installation rules still apply.');}
function about(){closeDrawer();options('DB Manager · 0.2.2',[{icon:'phone',label:'User info (local)',run:async()=>{const name=await ask('Local profile name',storage.get('cyber-name')||'DB');if(name!==null){storage.set('cyber-name',name);toast('Profile updated');}}},{icon:'info',label:'User guide',run:guide},{icon:'history',label:'Release notes',run:()=>alertBox('Version 0.2.2','APKS conversion: base and configuration splits merge into a signed, verified APK. Choose bundletool variants separately; standalone APKs preserve a valid signature. APKS remains unchanged. Play asset packs and unsupported delivery types report a clear error.\n\nPerformance and Java editing update: compositor pinch preview; no full-buffer typing scans; reusable menu animations; independent thumbnail queue; editable Java with ECJ/DEX compilation and diagnostics; undoable find/replace; verified Save and sign with backup. Device FPS is not measured here.\n\nEarlier interaction update: sidebar overflow and edge swipes; animated menus, dialogs, row feedback and package expansion; editor-side options; pinch zoom in Java, Smali, XML and text with separate remembered sizes. Opening the sidebar does not save unsaved code.\n\nPrevious video update: member/string Navigation; usage, subclass and override search; member/code/snippet copying; line and register tools; Save and exit with .bak backup; Restore swap; multi-selection, compare and bookmarks; 9 archive formats with password/split controls. Startup recovery and compact layouts are retained.\n\nFeatures: dual-panel file manager; APK explorer, manifest editor and signing; MultiDex, Smali and Java editor; local file tools, terminal, FTP/FTPS and read-only sharing/MCP.\n\nBuilt independently for DB Manager. No original app code is included.')},{icon:'layers',label:'Open-source credits',run:()=>alertBox('Open-source credits','JADX (Apache-2.0)\nsmali / baksmali / dexlib2 (BSD-3-Clause)\nCodeMirror 5 (MIT)\nAndroid apksig (Apache-2.0)\nARSCLib 1.4.0 (Apache-2.0)\nECJ 4.6.1 (EPL-1.0) · AOSP dx (Apache-2.0) · ASM (BSD-3-Clause)\nApache Commons Net (Apache-2.0)\nGuava, Gson, Protobuf, ANTLR and SLF4J\n\nDependency versions and license notices are included in the source package.')}]);}
window.goBack=async()=>{try{if($('#menuLayer').children.length){closeMenu();return;}if($('#modalLayer').children.length){closeModal();return;}if($('#drawerLayer').children.length){closeDrawer();return;}if(state.screen==='editor'){if(!await canLeave())return;const back=state.editor.returnScreen;if(state.disposeEditor)state.disposeEditor();state.cm=null;state.editor=null;$('#content').classList.remove('javaEditor');if(back==='dex')await renderDex();else await refresh();state.screen=back==='dex'?'dex':'files';if(back!=='dex')renderFiles();return;}if(state.screen==='tool'){if(state.previous==='dex')await renderDex();else{state.screen='files';await refresh();}return;}if(state.screen==='dex'){if(state.dex.tab!=='explorer'){state.dex.tab='explorer';await renderDex();}else await closeDex();return;}if(selectedFiles().length){clearSelection();return;}if(activePane().history.length)await backPane();else if(!activePane().archive&&['/',state.info.home,state.info.workspace].includes(activePane().path))await rpc('exit');else await up();}catch(e){alertBox('Could not complete',e.message);}};
let initialized=false;window.onNativeResume=()=>{if(initialized)act(async()=>{const old=state.info.permission;state.info=await rpc('init');if(!old&&state.info.permission){state.panes[0].path=state.info.home;state.panes[1].path=state.info.home+'/Download';}if(state.screen==='files')await refresh();});};
/* ===== APK tools: manifest, clone, permissions, entries, hex, project, ARSC strings, signing key ===== */
const TOOL=(op,a={})=>rpc('apkTool',Object.assign({op},a));
function defaultDir(){return state.info.permission?state.info.home+'/Download':state.info.workspace;}
function form(title,fields,ok='OK',note=''){return new Promise(resolve=>{const body=(note?`<p class="subtitle">${esc(note)}</p>`:'')+fields.map(f=>f.type==='check'?`<label class="checkRow"><input type="checkbox" id="f_${f.id}"${f.value?' checked':''}> <span>${esc(f.label)}</span></label>`:`<label for="f_${f.id}">${esc(f.label)}</label><input id="f_${f.id}" type="${f.type||'text'}" value="${esc(f.value||'')}" placeholder="${esc(f.placeholder||'')}" autocomplete="off" spellcheck="false">`).join('');dialog(title,body,[['Cancel',()=>{modalCancel=null;closeModal();resolve(null);}],[ok,()=>{const v={};for(const f of fields){const el=$('#f_'+f.id);v[f.id]=f.type==='check'?el.checked:el.value;}modalCancel=null;closeModal();resolve(v);}]],()=>resolve(null));});}
async function toolDone(title,out){await refresh();const p=out.path||String(out),apk=/\.apk$/i.test(p);dialog(title,`<p class="break">${esc(p)}</p>${out.signed?'<p class="subtitle">Signed and verified (V1, V2, V3).</p>':''}${out.backup?'<p class="subtitle">Backup: '+esc(out.backup)+'</p>':''}`,[['Close',closeModal],...(apk?[['Install',async()=>{closeModal();await rpc('install',{path:p});}]]:[])]);}
async function apkEdit(info,clone){const m=await TOOL('manifestInfo',{path:info.path});const v=await form(clone?'Clone APK':'Edit manifest',[{id:'package',label:'Package name',value:m.package},{id:'label',label:'App name (empty = keep)',value:/^@/.test(m.label)?'':m.label},{id:'versionName',label:'Version name',value:m.versionName},{id:'versionCode',label:'Version code',value:m.versionCode,type:'number'},{id:'sign',label:'Sign the result',value:true,type:'check'}],clone?'Clone':'Apply',clone?'Makes a new APK with another package name so it installs next to the original. The original is never changed.':'Writes a new -edited.apk next to the original.');if(!v)return;if(clone&&v.package===m.package)throw new Error('Choose a different package name for the clone');toolDone(clone?'Cloned APK':'Edited APK',await TOOL(clone?'clone':'manifestApply',{path:info.path,package:v.package===m.package?'':v.package,label:v.label,versionName:v.versionName===m.versionName?'':v.versionName,versionCode:v.versionCode===m.versionCode?'':v.versionCode,sign:v.sign}));}
async function apkPerms(info){const m=await TOOL('manifestInfo',{path:info.path});if(!m.permissions.length){alertBox('Permissions','This APK requests no permissions.');return;}const ads=/AD_ID|ADSERVICES|ADVERTIS/i;const fields=[{id:'all',label:'Remove ALL permissions',type:'check',value:false},...m.permissions.map((p,i)=>({id:'p'+i,label:p,type:'check',value:ads.test(p)})),{id:'sign',label:'Sign the result',type:'check',value:true}];const v=await form('Remove permissions',fields,'Remove','Tick the permissions to remove. Advertising-ID permissions are pre-ticked. Removing a permission the app needs can make it crash.');if(!v)return;const names=m.permissions.filter((p,i)=>v['p'+i]);if(!v.all&&!names.length){toast('Nothing ticked');return;}toolDone('Edited APK',await TOOL('manifestApply',{path:info.path,removePermissions:names,removeAllPermissions:v.all,sign:v.sign}));}
async function apkAddFile(info){const entry=await ask('Path inside the APK','assets/','Example: res/drawable/icon.png');if(!entry)return;const src=await ask('File on your phone',defaultDir()+'/','Replaces the entry if it exists, otherwise adds it');if(!src)return;toolDone('Edited APK',await TOOL('replaceEntry',{archive:info.path,entry,source:src,add:true,sign:true}));}
async function entryReplace(f){const a=fileArgs(f),src=await ask('Replacement file on your phone',defaultDir()+'/','Replaces '+a.entry+' (images must be the same type)');if(!src)return;toolDone('Edited archive',await TOOL('replaceEntry',{archive:a.archive,entry:a.entry,source:src,sign:/\.apk$/i.test(a.archive)}));}
async function entryRemove(files){const a=files.map(fileArgs);if(!await confirmBox('Remove from archive','Removes '+a.length+' file(s) and writes a new copy. The original stays unchanged.','Remove'))return;toolDone('Edited archive',await TOOL('deleteEntries',{archive:a[0].archive,entries:a.map(x=>x.entry),sign:/\.apk$/i.test(a[0].archive)}));}
const hex6=n=>n.toString(16).toUpperCase().padStart(6,'0');
async function hexView(args,off=0){const r=await TOOL('hexRead',Object.assign({},args,{offset:off,length:512}));const rows=r.rows.map(x=>{const h=x.hex.split(' ');return `<div class="hexRow"><span class="hexOff">${hex6(x.offset)}</span> <span class="hexBytes">${h.slice(0,8).join(' ')}</span> <span class="hexAscii">${esc(x.ascii.slice(0,8))}</span></div><div class="hexRow"><span class="hexOff">${hex6(x.offset+8)}</span> <span class="hexBytes">${h.slice(8).join(' ')}</span> <span class="hexAscii">${esc(x.ascii.slice(8))}</span></div>`;}).join('');const name=(args.entry||args.path||'').split('/').pop();const btn=[['Close',closeModal],['Go to',async()=>{const v=await ask('Go to offset','0x'+r.offset.toString(16),'Decimal or 0x hex');if(v!==null)hexView(args,Number(v)||0);}],['Find',async()=>{const v=await ask('Find','','Hex bytes like 1F 8B, or "text" in quotes');if(!v){hexView(args,r.offset);return;}const t=/^\s*"(.*)"\s*$/.exec(v);const res=await TOOL('hexFind',Object.assign({},args,{pattern:t?t[1]:v,text:!!t}));if(!res.hits.length){alertBox('Find','No match.');return;}options('Matches ('+res.hits.length+(res.hits.length>=200?'+':'')+')',res.hits.slice(0,60).map(h=>({label:'0x'+h.toString(16).toUpperCase()+'  ('+h+')',run:()=>hexView(args,h)})));}],['Patch',async()=>{const v=await form('Patch bytes',[{id:'off',label:'Offset (decimal or 0x hex)',value:'0x'+r.offset.toString(16)},{id:'hex',label:'New bytes (hex, same length is overwritten)',placeholder:'90 90'}],'Write',args.archive?'Writes a new signed copy. The original is kept.':'The file is changed in place; a .bak backup is kept once.');if(!v)return;const o=Number(v.off);if(!Number.isFinite(o)||o<0)throw new Error('Offset is not a number');const out=await TOOL('hexPatch',Object.assign({},args,{patches:[{offset:o,hex:v.hex}]}));if(out.path&&args.archive)toolDone('Patched copy',out);else{toast('Patched');hexView(args,o);}}]];if(r.offset>0)btn.push(['◀',()=>hexView(args,Math.max(0,r.offset-512))]);if(r.offset+512<r.total)btn.push(['▶',()=>hexView(args,r.offset+512)]);dialog('Hex · '+name,`<div class="subtitle">${r.total} bytes · offset ${r.offset} (0x${r.offset.toString(16).toUpperCase()})</div><div class="hexView">${rows}</div>`,btn);}
async function projDecode(info){const v=await form('Decode to project folder',[{id:'dest',label:'Destination folder',value:defaultDir()},{id:'name',label:'Folder name',value:info.package+'-project'}],'Decode','Extracts every file and turns binary XML (manifest, layouts, drawables) into editable text. resources.arsc and DEX stay as they are: use String resources and the DEX editor for those.');if(!v)return;const out=await TOOL('projectDecode',{path:info.path,destination:v.dest,name:v.name});await refresh();alertBox('Project ready',out.path+'\n'+out.files+' files, '+out.xmlDecoded+' XML decoded'+(out.xmlKeptBinary?', '+out.xmlKeptBinary+' kept binary':'')+'.\nEdit the files, then select the folder → Build APK project.');}
async function projBuild(f){const v=await form('Build APK project',[{id:'name',label:'Output name (without .apk)',value:f.name+'-rebuilt'},{id:'sign',label:'Sign the result',type:'check',value:true}],'Build','Rebuilds from the original APK plus your changes. The original APK must still exist.');if(!v)return;toolDone('Built APK',await TOOL('projectBuild',{folder:await rpc('resolve',fileArgs(f)),name:v.name,sign:v.sign}));}
async function arscEdit(info,q=''){const r=await TOOL('arscStrings',{path:info.path,query:q,limit:200});const rows=r.items.map(x=>`<button class="arscRow" data-i="${x.index}">${esc(x.text.length>90?x.text.slice(0,90)+'…':x.text)||'(empty)'}</button>`).join('')||'<p>No strings match.</p>';const d=dialog('String resources',`<div class="subtitle">${r.total} strings${q?' · filter: '+esc(q):''}. Tap one to edit. It changes every place that uses exactly this text.</div><div class="arscList">${rows}</div>`,[['Close',closeModal],['Filter',async()=>{const v=await ask('Filter strings',q);if(v!==null)arscEdit(info,v);}]]);d.querySelectorAll('.arscRow').forEach(b=>b.onclick=async()=>{const i=Number(b.dataset.i),cur=r.items.find(x=>x.index===i).text;closeModal();const v=await ask('Edit string #'+i,cur);if(v===null||v===cur){arscEdit(info,q);return;}toolDone('Edited strings',await TOOL('arscReplace',{path:info.path,changes:[{index:i,text:v}],sign:true}));});}
async function securitySuite(args){
 const rows=[
  {icon:'layers',label:'Anti-Dump / Runtime checks',run:()=>protectApk(args)},
  {icon:'dex',label:'Inspect DEX',run:()=>chooseDex(args)},
  {icon:'shield',label:'DumpDex script requirements',run:()=>alertBox('DumpDex / Anti-Dump','DumpDex.js is a Frida runtime script and is not an APK protection switch. It requires a compatible Frida setup and authorized target. For protection, use Protect APK → Frida/Xposed detection and DEX/resource integrity checks. These checks raise the cost of dumping but cannot guarantee that runtime DEX extraction is impossible.')},
  {icon:'key',label:'DEX Shell / DEX encryption',run:()=>alertBox('DEX Shell / Encryption','Not yet implemented in this DB Manager build. Real DEX encryption needs a compatible runtime loader and must preserve multidex, class loading, reflection, JNI, and Android-version behavior. A menu item alone would not encrypt the APK.')},
  {icon:'zip',label:'Assets / Resource protection',run:()=>alertBox('Assets / Resource protection','Not yet implemented as encryption. The existing Protect APK → DEX/resources integrity check can detect some post-build changes; it does not encrypt resources. Actual encryption requires a compatible runtime decryption path and app-specific testing.')},
  {icon:'layers',label:'DEX VMP Plus / Control Flow',run:()=>alertBox('DEX VMP Plus','Not yet implemented. Real control-flow transformation requires bytecode rewriting and verification tests; this menu does not claim to transform classes.')},
  {icon:'check',label:'Signature protection',run:()=>protectApk(args)}
 ];
 options('APK Security Suite',rows);
}
async function protectApk(args){
 const info=await TOOL('protectInfo',args);
 if(info.hasCustomApplication){
  alertBox('Protect APK','This APK already has a custom Application class ('+info.existingApplication+'). Protect APK cannot chain onto it yet.');
  return;
 }
 
 const fields=[
  {id:'signatureCheck',label:'Signature Verification (Anti-Repack)',type:'check',value:true},
  {id:'rootCheck',label:'Root Detection',type:'check',value:true},
  {id:'debuggerCheck',label:'Debugger Detection',type:'check',value:true},
  {id:'emulatorCheck',label:'Emulator Detection',type:'check',value:false},
  {id:'fridaCheck',label:'Frida / Xposed Detection',type:'check',value:false},
  {id:'integrityCheck',label:'Integrity Check (DEX, resources, libs)',type:'check',value:false},
  {id:'screenshotBlock',label:'Block Screenshots (FLAG_SECURE)',type:'check',value:false},
  {id:'tapjackingCheck',label:'Tapjacking Protection',type:'check',value:false},
  {id:'mitmCheck',label:'MITM Proxy Detection',type:'check',value:false},
  {id:'accessibilityCheck',label:'Block Non-System Accessibility Services',type:'check',value:false},
  {id:'overlayCheck',label:'Overlay Detection',type:'check',value:false},
  {id:'usbDebugCheck',label:'USB Debugging Detection',type:'check',value:false},
  {id:'cloningCheck',label:'App Cloning / Parallel Space Detection',type:'check',value:false},
  {id:'suspiciousAppsCheck',label:'Scan for Suspicious Analysis Apps',type:'check',value:false},
  {id:'installSourceCheck',label:'Installer Source Check',type:'check',value:false},
  {id:'installSourcePackages',label:'Allowed installers (comma-separated)',placeholder:'com.android.vending'},
  {id:'expiryCheck',label:'Expiry Date Check',type:'check',value:false},
  {id:'expiryDate',label:'Expiry date',type:'date'},
  {id:'disableBackup',label:'Disable Backup (adb backup)',type:'check',value:false},
  {id:'forceNonDebuggable',label:'Force Non-Debuggable',type:'check',value:false},
  {id:'timeTamperCheck',label:'Time Tampering Detection',type:'check',value:false},
  {id:'deviceBindingCheck',label:'Device Binding (Lock to first device)',type:'check',value:false},
  {id:'guardSelfCheck',label:'Guard Self-Check (Anti-tamper)',type:'check',value:false},
  {id:'dexEncryption',label:'DEX Shell / Encryption (API 26+)',type:'check',value:false}
 ];
 
 const v=await form('Protect APK',fields,'Protect','Adds a self-contained runtime guard. The original APK is never changed.');
 if(!v)return;
 
 const anyChecked = Object.keys(v).some(k => v[k] === true && k.endsWith('Check'));
 if(!anyChecked && !v.dexEncryption){toast('Choose at least one protection');return;}
 if(v.installSourceCheck && !v.installSourcePackages.trim()){toast('Enter at least one allowed installer package');return;}
 if(v.expiryCheck && !v.expiryDate){toast('Choose an expiry date');return;}
 
 toolDone('Protected APK', await TOOL('protect', Object.assign({}, args, v)));
}